        {ReviewStatusTrailerKey, md.Status},
    }
    out := message
    for _, t := range trailers {
        if t.val == "" {
            continue
        }
        out = appendTrailerLine(out, fmt.Sprintf("%s: %s", t.key, t.val))
    }
    return out
}
